python3 << 'EOF'
import os

font_dirs = [
    '/System/Library/Fonts',
    '/System/Library/Fonts/Supplemental',
    '/Library/Fonts'
]

chinese_keywords = ['Song', 'Fang', 'Kai', 'Hei', 'Kai', 'Ming', 'ST', 'Ping', 'Hana']
chinese_fonts = []

for font_dir in font_dirs:
    if os.path.exists(font_dir):
        for root, dirs, files in os.walk(font_dir):
            for file in files:
                if file.endswith(('.ttf', '.ttc', '.otf')):
                    for keyword in chinese_keywords:
                        if keyword in file:
                            chinese_fonts.append(os.path.join(root, file))
                            break

print('系统中可能包含中文的字体:')
for font in sorted(set(chinese_fonts)):
    print(f'  {os.path.basename(font)}')
EOF

python3 << 'EOF'
from fontTools.ttLib import TTFont
import os

font_dir = os.path.expanduser('~/Library/Fonts')
source_han_fonts = []

for file in os.listdir(font_dir):
    if file.startswith('SourceHan'):
        try:
            font_path = os.path.join(font_dir, file)
            font = TTFont(font_path)
            name_table = font['name']

            font_info = {'file': file}
            for record in name_table.names:
                if record.nameID in [1, 2, 4]:  # Family, Subfamily, Full name
                    try:
                        key = {1: 'family', 2: 'subfamily', 4: 'fullname'}[record.nameID]
                        font_info[key] = record.toUnicode()
                    except:
                        pass

            source_han_fonts.append(font_info)
        except Exception as e:
            pass

print('已安装的思源字体:\n')
for font in source_han_fonts:
    if 'family' in font:
        print(f"  {font['family']} {font.get('subfamily', '')}")
EOF
